/**
 * Which set of materials the dungeon's generic floors and walls are drawn in.
 *
 * Floors 1 and 2 are generated by the same `DungeonGenerator` and carry the same
 * five tile types — `wall` plus the four generic floors `ZONE_FLOORS` assigns —
 * so the only thing that can distinguish them visually is the palette those
 * types are resolved through. A theme is that palette, plus the material a wall
 * is drawn in.
 *
 * ## Why the active theme is module state
 *
 * Nothing between `GameMap.renderCanvas` and the tile painters carries any level
 * identity: `TileChunkCache` is constructed from a structure grid and a tile
 * size, `drawTile` dispatches on a tile type, and `drawTerrainTile` is reached
 * from ten call sites in `decorationTiles.ts` and `interiorTiles.ts` that draw
 * the floor underneath a prop. Threading a palette to all of them would change
 * fourteen signatures to pass a value that is constant for the entire lifetime
 * of a map.
 *
 * So it is set once, on the one event that can change it — entering a floor —
 * and read by the painters, in the same way `getSpriteDef` is read. Exactly one
 * map is live at a time, and changing floor builds a new `GameMap` and therefore
 * a new chunk cache, so no baked chunk can outlive the theme it was baked under.
 *
 * A town building interior is a separate map with tile types of its own —
 * `INTERIOR_BOARD_FLOOR`, `INTERIOR_STONE_FLOOR`, `INTERIOR_WALL` and
 * `INTERIOR_COUNTER`, drawn through `TOWN_INTERIOR_GROUND`. Those types exist so
 * an interior's floor and wall art is independent of the dungeon theme: sharing
 * the generic `FloorTypeValue.wood`/`carpet`/`wall` types would make a
 * townhouse's floorboards resolve through whichever dungeon theme happens to be
 * active, rather than through the interior's own palette.
 */

import type { GroundPalette } from '../ground/GroundPalette';
import { FLOOR1_GROUND, FLOOR1_WALL_MATERIAL } from './floor1Materials';
import { FLOOR2_GROUND, FLOOR2_WALL_MATERIAL } from './floor2Materials';
import { SEWER_GROUND, SEWER_WALL_MATERIAL } from './sewerMaterials';

export interface DungeonFloorTheme {
  /** Which floor this is; the wall painter keys its faces, slivers and dressing on it. */
  readonly id: DungeonFloorThemeId;
  /** The palette the four generic dungeon floor types resolve through. */
  readonly ground: GroundPalette;
  /**
   * The material a `FloorTypeValue.wall` tile is drawn in.
   *
   * Held here rather than reached through `materialForTileType` because a wall
   * must not be a *fringe* material: the corner masks would blend masonry into
   * the floor in front of it as though a wall were another kind of ground.
   */
  readonly wallMaterial: string;
}

/** Every theme, for the review tools that draw each one side by side. */
export const DUNGEON_FLOOR_THEME_IDS = ['cellars', 'service_level', 'sewer'] as const;

export type DungeonFloorThemeId = (typeof DUNGEON_FLOOR_THEME_IDS)[number];

/**
 * Whether `DungeonGenerator` lays floors in each theme. The sewer is a
 * hand-built map under the town, drawn in this pipeline's walls and water but
 * never generated, so it carries none of the generator's furniture — no room
 * and hallway characters, and no crawler signs pointing to stairs.
 */
const GENERATED_THEMES = {
  cellars: true,
  service_level: true,
  sewer: false,
} as const satisfies Record<DungeonFloorThemeId, boolean>;

/** The themes `DungeonGenerator` lays floors in, and so the only ones a `LevelDef` may declare. */
export type GeneratedFloorThemeId = {
  [Id in DungeonFloorThemeId]: (typeof GENERATED_THEMES)[Id] extends true ? Id : never;
}[DungeonFloorThemeId];

export function isGeneratedFloorTheme(id: DungeonFloorThemeId): id is GeneratedFloorThemeId {
  return GENERATED_THEMES[id];
}

const THEMES: Readonly<Record<DungeonFloorThemeId, DungeonFloorTheme>> = {
  cellars: { id: 'cellars', ground: FLOOR1_GROUND, wallMaterial: FLOOR1_WALL_MATERIAL },
  service_level: {
    id: 'service_level',
    ground: FLOOR2_GROUND,
    wallMaterial: FLOOR2_WALL_MATERIAL,
  },
  sewer: { id: 'sewer', ground: SEWER_GROUND, wallMaterial: SEWER_WALL_MATERIAL },
};

/**
 * What a level with no `groundTheme` of its own is drawn in.
 *
 * Nothing reaches it today — every `LevelDef` names a theme, and a town building
 * interior has tile types of its own — so this is the answer to "a floor was
 * added and nobody said what it is made of", not a live code path. Floor 1's,
 * because a floor that forgot to declare itself is far more likely to be an
 * early one.
 *
 * It is still applied *unconditionally* on every level entry rather than only
 * when a level names a theme. That is what makes the active theme a property of
 * the level being entered instead of a leftover from the last one, and it is
 * cheap insurance: the failure it prevents is silent and only shows up as art
 * from the wrong floor.
 */
export const DEFAULT_DUNGEON_FLOOR_THEME = 'cellars' as const satisfies GeneratedFloorThemeId;

let activeTheme: DungeonFloorTheme = THEMES[DEFAULT_DUNGEON_FLOOR_THEME];
let activeClaim: symbol | null = null;

/** Sets the materials every dungeon floor and wall is drawn in from now on. */
export function setDungeonFloorTheme(id: DungeonFloorThemeId): void {
  activeTheme = THEMES[id];
  activeClaim = null;
}

/**
 * Sets the theme for something that lives inside another map's visit (the
 * sewer under the town), and returns the release that puts the previous theme
 * back. The release does nothing once anything has set a theme since: the
 * next scene is built before the old one is torn down, so a release that ran
 * unconditionally would paint the new map in the theme from before the claim.
 */
export function claimDungeonFloorTheme(id: DungeonFloorThemeId): () => void {
  const previous = activeTheme;
  const claim = Symbol('dungeonFloorThemeClaim');
  activeTheme = THEMES[id];
  activeClaim = claim;
  return () => {
    if (activeClaim !== claim) return;
    activeTheme = previous;
    activeClaim = null;
  };
}

/** The materials dungeon floors and walls are currently drawn in. */
export function dungeonFloorTheme(): DungeonFloorTheme {
  return activeTheme;
}
